/**
 * 负责恶灵骑士私有状态、查验反射权利及玩家字段投影；输入是原角色与查验上下文。
 * 保留免疫检查、反射付款与原体绑定；运行状态引用不是玩家 DTO，替换状态不能复用旧权利。
 * 玩家投影只复制政策、枪政策与反射余量，不交出 isCurrent 或写句柄。
 */
import type {
  EvilKnightShotPolicy,
  EvilKnightState,
  EvilKnightReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId } from "../../../../core/domain/identity";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
  type NightRetaliationAttack,
} from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";

export const EVIL_KNIGHT_ROLE = "evil_knight" as const;
export const EVIL_KNIGHT_POLICY = "awa_evil_knight_v1" as const;
function data(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
export function freshEvilKnightState(
  shotPolicy: EvilKnightShotPolicy = "night_shot_immune",
): EvilKnightState {
  return { policy: EVIL_KNIGHT_POLICY, shotPolicy, reflectionRemaining: 1 };
}
export function getEvilKnightState(
  role: RoleComponent | undefined,
): EvilKnightReadState | undefined {
  if (data(role, "role") !== EVIL_KNIGHT_ROLE || data(role, "camp") !== Camp.Wolf) return undefined;
  const state = data(data(role, "privateState"), "evilKnight");
  const shot = data(state, "shotPolicy"),
    remaining = data(state, "reflectionRemaining");
  return data(state, "policy") === EVIL_KNIGHT_POLICY &&
    (shot === "night_shot_immune" || shot === "hunter_shot_bypasses") &&
    (remaining === 0 || remaining === 1)
    ? (state as EvilKnightReadState)
    : undefined;
}
/** 在等待其他玩家提交前绑定原体；每次提交仍校验生命、组件、私有容器与政策未被替换。 */
export function captureEvilKnight(world: World, target: NightLifeScope) {
  const role = world.getComponent(target.id, COMPONENT.Role);
  const state = getEvilKnightState(role);
  if (!role || !state || !livingNightLife(world, target)) return null;
  const privateState = role.privateState,
    shotPolicy = state.shotPolicy;
  const isCurrent = () =>
    livingNightLife(world, target) &&
    world.getComponent(target.id, COMPONENT.Role) === role &&
    role.privateState === privateState &&
    getEvilKnightState(role) === state &&
    state.shotPolicy === shotPolicy;
  return { target, state, isCurrent };
}
export function evilKnightNightShotImmune(world: World, targetId: EntityId): boolean {
  const life = captureNightLife(world, targetId);
  const binding = life && captureEvilKnight(world, life);
  return !!binding && binding.state.shotPolicy === "night_shot_immune" && binding.isCurrent();
}
/** 仅在原生预言家查验或女巫毒药已被接受并付款后调用；反射本身不重复消耗原行动。 */
export function commitEvilKnightReflection(
  world: World,
  binding: ReturnType<typeof captureEvilKnight>,
  caster: NightLifeScope,
  trigger: "seer_check" | "poison",
  casterCurrent: () => boolean,
): NightRetaliationAttack | null {
  const casterRole = world.getComponent(caster.id, COMPONENT.Role);
  const expected = trigger === "seer_check" ? Role.Seer : Role.Witch;
  if (
    !binding ||
    !binding.isCurrent() ||
    binding.state.reflectionRemaining !== 1 ||
    !livingNightLife(world, caster) ||
    !casterCurrent() ||
    casterRole?.role !== expected ||
    casterRole.camp !== Camp.Good
  )
    return null;
  const privateState = casterRole.privateState;
  (binding.state as Pick<EvilKnightState, "reflectionRemaining">).reflectionRemaining = 0;
  return {
    actorId: binding.target.id,
    target: caster,
    isCurrent: () =>
      binding.isCurrent() &&
      binding.state.reflectionRemaining === 0 &&
      livingNightLife(world, caster) &&
      casterCurrent() &&
      world.getComponent(caster.id, COMPONENT.Role) === casterRole &&
      casterRole.role === expected &&
      casterRole.camp === Camp.Good &&
      casterRole.privateState === privateState,
  };
}

/** 字段裁剪由机制拥有；只返回纯数据副本，不把反射运行绑定带进玩家观察。 */
export function projectEvilKnightState(
  role: RoleComponent | undefined,
): EvilKnightState | undefined {
  const evilKnight = getEvilKnightState(role);
  if (evilKnight)
    return {
      policy: evilKnight.policy,
      shotPolicy: evilKnight.shotPolicy,
      reflectionRemaining: evilKnight.reflectionRemaining,
    };
}

/**
 * 负责 恶夜骑士 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Role, WinCondition } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { EVIL_KNIGHT_POLICY, freshEvilKnightState, getEvilKnightState } from "./state";
import { EVIL_KNIGHT_FRAME_STAGE } from "./night_frame";
const parameters = z.strictObject({
  policy: z.literal(EVIL_KNIGHT_POLICY).default(EVIL_KNIGHT_POLICY),
  shotPolicy: z.enum(["night_shot_immune", "hunter_shot_bypasses"]).default("night_shot_immune"),
});
export const EVIL_KNIGHT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.EvilKnight,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.EvilKnight,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
    ],
    label: roleName("evil_knight"),
    skillBrief: text("zh-CN", "role.evil_knight.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: false,
    toolSpecs: (ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs ?? []).filter(
      (spec) => spec.name !== "self_destruct" && spec.name !== "self_destruct_with_target",
    ),
    init: (role, ctx) => {
      role.privateState.evilKnight = freshEvilKnightState(
        parameters.parse(ctx.boardConfig?.evilKnight ?? {}).shotPolicy,
      );
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, evilKnight: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.evilKnight ?? {}),
    },
    nightStages: [EVIL_KNIGHT_FRAME_STAGE, ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages ?? [])],
  },
  presentation: nativeRolePresentation("evil_knight"),
};

/**
 * 负责恶夜骑士固定名单的原体复验及本夜绑定捕获阶段。输入为原玩家、能力身份与当前夜状态；
 * 输出为原名单拒绝、同一 binding Map 与免疫提案。名单不在角色替换后重建，失效保原错误前缀。
 * 每次状态读取和原 capture／Map.set 顺序保持；本族登记 Map 后才展开免疫数组，后续失败不退款或撤销安装。
 * 捕获数据与反射资源的原体资格仍归 state；运行回调／生命引用不进入玩家观察或归档，也不授权行动。
 */
import type { World } from "../../../../core/domain/world";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role } from "../../../../core/domain/identity";
import { captureNightLife } from "../../../../core/domain/night_effects";
import type { NightStageHandler } from "../../stages/night/contracts";
import { captureEvilKnight } from "./state";
import { hasEvilKnightNightBindings, installEvilKnightNightBindings } from "./night-bindings";
import type { NightAbilityReadView } from "../abilities";
type AbilityAuthority = {
  ability: NightAbilityReadView;
  state: NightAbilityReadView["state"];
  source: NightAbilityReadView["source"];
  identity: string;
};
function abilityIdentity(ability: NightAbilityReadView): string {
  const state = ability.state as unknown as Record<string, unknown>;
  return JSON.stringify([
    ability.id,
    ability.kind,
    ability.activation,
    ability.source,
    ability.sourceDisclosed,
    ability.startsOnDay,
    ability.expiresAfterDay,
    ability.maxUses,
    state.targetPolicy,
    state.actionPolicy,
    state.selfHealRule,
    state.knifeVisibility,
    state.potionPolicy,
    state.repeatPolicy,
    state.policy,
    state.inspectionPolicy,
    state.protectionPolicy,
  ]);
}
type RosterBinding = {
  id: number;
  role: RoleComponent;
  kind: Role;
  camp: Camp;
  state: RoleComponent["privateState"];
  refs: [string, unknown][];
  abilityRefs: [string, unknown][];
  authorities: AbilityAuthority[];
};
const installed = new WeakMap<World, RosterBinding[]>();
export function installEvilKnightBoard(world: World): void {
  if (installed.has(world)) throw new Error("evil_knight_board_reinstall");
  installed.set(
    world,
    world.entityIds().map((id) => {
      const role = world.getComponent(id, COMPONENT.Role);
      if (!role) throw new Error("evil_knight_roster_missing");
      return {
        id,
        role,
        kind: role.role,
        camp: role.camp,
        state: role.privateState,
        refs: Object.entries(role.privateState),
        abilityRefs: Object.entries(
          (role.privateState as { readonly abilities?: unknown }).abilities ?? {},
        ),
        authorities: Object.values(
          ((role.privateState as { readonly abilities?: unknown }).abilities ?? {}) as Record<
            string,
            NightAbilityReadView
          >,
        ).map((ability) => ({
          ability,
          state: ability.state,
          source: ability.source,
          identity: abilityIdentity(ability),
        })),
      };
    }),
  );
}
export function isEvilKnightBoard(world: World): boolean {
  return installed.has(world);
}
export function assertEvilKnightRosterCurrent(world: World): void {
  for (const entry of installed.get(world) ?? []) {
    if (
      world.getComponent(entry.id, COMPONENT.Role) !== entry.role ||
      entry.role.role !== entry.kind ||
      entry.role.camp !== entry.camp ||
      entry.role.privateState !== entry.state ||
      entry.refs.some(
        ([key, value]) => (entry.state as Readonly<Record<string, unknown>>)[key] !== value,
      ) ||
      entry.authorities.some(
        (a) =>
          a.ability.state !== a.state ||
          a.ability.source !== a.source ||
          abilityIdentity(a.ability) !== a.identity,
      ) ||
      Object.keys((entry.state as { readonly abilities?: unknown }).abilities ?? {}).length !==
        entry.abilityRefs.length ||
      entry.abilityRefs.some(
        ([key, value]) =>
          (
            (entry.state as { readonly abilities?: unknown }).abilities as
              Record<string, unknown> | undefined
          )?.[key] !== value,
      )
    )
      throw new Error("evil_knight_roster_revoked");
  }
}
export function assertEvilKnightNativeActor(world: World, actorId: number, expected: Role): void {
  if (!isEvilKnightBoard(world)) return;
  assertEvilKnightRosterCurrent(world);
  const role = world.getComponent(actorId, COMPONENT.Role);
  if (role?.role !== expected || role.camp !== Camp.Good)
    throw new Error("evil_knight_actor_identity_revoked");
}
export const EVIL_KNIGHT_FRAME_STAGE: NightStageHandler = {
  id: "evil_knight_frame",
  priority: 50,
  async execute(ctx) {
    if (!isEvilKnightBoard(ctx.world)) return;
    assertEvilKnightRosterCurrent(ctx.world);
    if (hasEvilKnightNightBindings(ctx.state)) throw new Error("evil_knight_night_reentry");
    const bindings = new Map<number, NonNullable<ReturnType<typeof captureEvilKnight>>>();
    for (const id of ctx.world.getAliveEntityIds()) {
      const life = captureNightLife(ctx.world, id);
      const binding = life && captureEvilKnight(ctx.world, life);
      if (binding) bindings.set(id, binding);
    }
    installEvilKnightNightBindings(ctx.state, bindings);
    ctx.state.nightImmunities = [...bindings.values()];
  },
};

/**
 * 负责恶夜骑士一夜原体绑定 Map 的唯一存储及反射／夜枪运行查询。
 * 输入为原 NightStageState 身份与开夜捕获的同一 Map；输出为原 binding 或捕获同一 Map 的夜枪闭包。
 * 原 binding 包含生命、库存引用和当前性回调，不是玩家 DTO 或 JSON，也不因查询而获得反射付款权限。
 * 原体捕获、免疫提案与反射资源消费仍归 night_frame／state；本模块不查询 World、不复制 Map 或重抓角色。
 * 旧通用 map 属性／返回 map 注入接口退出；更换状态对象不接续旧 Map，已有结果闭包保原捕获引用。
 */
import type { EntityId } from "../../../../core/domain/identity";
import type { NightStageState } from "../../stages/night/contracts";
import type { captureEvilKnight } from "./state";

type EvilKnightNightBinding = NonNullable<ReturnType<typeof captureEvilKnight>>;
type EvilKnightNightBindings = Map<EntityId, EvilKnightNightBinding>;

// 只有本族这一份按夜间状态身份登记的 Map；免疫列表仍是原独立提案数组，不挂通用镜像。
const bindingsByNight = new WeakMap<NightStageState, EvilKnightNightBindings>();

/** 仅核原重入检查点是否已安装；不调用 binding.isCurrent 或推导资格。 */
export function hasEvilKnightNightBindings(state: NightStageState): boolean {
  return bindingsByNight.has(state);
}

/** 在原赋值点登记同一 Map；values 迭代或随后免疫写入失败仍保留已经安装的前缀。 */
export function installEvilKnightNightBindings(
  state: NightStageState,
  bindings: EvilKnightNightBindings,
): void {
  bindingsByNight.set(state, bindings);
}

/** 反射在原参数读取点取得原 binding；原付款命令继续负责当前性、来源和资源复核。 */
export function evilKnightNightBinding(
  state: NightStageState,
  targetId: EntityId,
): EvilKnightNightBinding | null {
  return bindingsByNight.get(state)?.get(targetId) ?? null;
}

/**
 * 在原输出字段点只捕获同一 Map，不读取 World／目标／政策。闭包调用时保持原 get、
 * isCurrent 再 shotPolicy 的短路顺序及 receiver；只返回夜枪保护，不暴露可替换的 Map。
 */
export function captureEvilKnightNightShotProtection(
  state: NightStageState,
): (targetId: EntityId) => boolean {
  const bindings = bindingsByNight.get(state);
  return (targetId) => {
    const binding = bindings?.get(targetId);
    return (
      !!binding && binding.isCurrent() && binding.state.shotPolicy === "night_shot_immune"
    );
  };
}

/**
 * 负责恶夜骑士公开的只读普通狼刀目标贡献，并提供原状态读取、资格校验及反射提交入口。
 * 输入是绑定原 World 的目标序号，或具体原体／查验上下文；输出保留原存活角色允许结果，
 * 包括未安装专用板子时的原政策。查询错误原样传播，绑定不提前读组件或授予生命、反射写权。
 * 名单复验向夜间规则组合及阶段检查点公开原函数，不读写库存或开启行动窗口。
 * 资格与反射命令仍保留原来源校验、付款时点和 frame 写入；狼刀目标查询本身只读。
 * 反射终态与失败前缀由状态命令维护，出口不拦截错误或尝试回滚。
 */
import { Role, type EntityId } from "../../../../core/domain/identity";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { World } from "../../../../core/domain/world";
export { isEvilKnightBoard, assertEvilKnightNativeActor, assertEvilKnightRosterCurrent } from "./night_frame";
export { commitEvilKnightReflection } from "./state";
/** 运行查询保原 binding／Map 捕获，不公开 Map 或增加库存／生命写权。 */
export { evilKnightNightBinding, captureEvilKnightNightShotProtection } from "./night-bindings";

export interface EvilKnightKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

export function bindEvilKnightKnifeTargetQuery(world: World): EvilKnightKnifeTargetQuery {
  return Object.freeze({
    allows: (targetId: EntityId) =>
      world.getComponent(targetId, COMPONENT.Role)?.role !== Role.EvilKnight,
  });
}

export { getEvilKnightState } from "./state";

/**
 * 负责完整捕获玩家可获知的身份、机制知识、已发表死亡、行动历史与能力／枪信息。
 * 输入为原请求与按原时点执行的窄查询；输出是原字段集合的脱离冻结 PlayerObservation。
 * World 仅在此游戏侧 adapter 读取，不交给策略；已知存活依发布事实计算，不替换为真实存活名单。
 * 角色和队友方法在 actor 参数之前查找；每个 World 读取保原位置，机制知识／权限仍归各原 owner。
 * 结构观察不提交行动、不克隆完整私有库存，也不提前执行自定义人设或角色展示回调；失败前缀保持。
 */
import { getWhiteWolfKingState } from "../mechanisms/roles/white_wolf_king/ports";
import { isAnimalDreamBoard } from "../mechanisms/roles/animal_dream/authority";
import {
  animalFoxKnowledge,
  animalPufferKnowledge,
  animalCatKnowledge,
  animalBeautyKnowledge,
  animalBearKnowledge,
} from "../mechanisms/roles/animal_dream/facts";
import {
  isNobleBodyBoard,
  getNobleBodyPlayerState,
} from "../mechanisms/roles/noble_secret_body/authority";
import {
  isFragrantPairBoard,
  fragrantPlayerKnowledge,
} from "../mechanisms/roles/fragrant_pair_seer/authority";
import { projectAlchemist, projectRaven } from "../mechanisms/roles/mist_raven/player_projection";
import { readModifierState } from "../mechanisms/roles/scholar_mentor/ports";
import { scholarMentorStateForRole } from "../mechanisms/roles/scholar_mentor/ports";
import { projectTimeConsortState } from "../mechanisms/roles/time_wolf_consort/ports";
import { projectWolfSorcererState } from "../mechanisms/roles/wolf_sorcerer/ports";
import { projectTricksterState } from "../mechanisms/roles/trickster/ports";
import { projectOrderPrinceState } from "../mechanisms/roles/order_prince/ports";
import { projectMagicianState } from "../mechanisms/roles/magician/ports";
import { projectRedMoonState } from "../mechanisms/roles/red_moon_apostle/ports";
import { projectNightmareShadowState } from "../mechanisms/roles/nightmare_shadow/ports";
import { projectEvilKnightState } from "../mechanisms/roles/evil_knight/state";
import { projectDemonHunter } from "../mechanisms/roles/demon_hunter/authority";
import { weddingActorView, weddingBrideState } from "../mechanisms/roles/ghost_bride/authority";
import { projectLonelyGirl } from "../mechanisms/roles/lonely_girl/lifecycle";
import { projectWildChild } from "../mechanisms/roles/wild_child/lifecycle";
import { projectShapeshifterState } from "../mechanisms/roles/shapeshifter/state";
import { projectShapeshifterChoices } from "../mechanisms/roles/shapeshifter/setup";
import { projectThiefState } from "../mechanisms/roles/thief/state";
import { projectThiefChoices } from "../mechanisms/roles/thief/setup";
import { projectWallNote } from "../mechanisms/events/wall_notes/authority";
import {
  projectBearState,
  projectDreamerState,
  projectGuardState,
  projectHunterState,
  projectIdiotState,
  projectKnightState,
  projectWhiteWolfKingState,
  projectWolfBeautyState,
  projectWolfKingState,
} from "../mechanisms/roles/player_state";
import { readGravekeeperReport } from "@ai-werewolf-arena/replay-contract";
import { getBearState } from "../mechanisms/roles/bear/ports";
import { getHiddenWolfState } from "../mechanisms/roles/hidden_wolf/ports";
import { canHiddenWolfKnife } from "../mechanisms/roles/hidden_wolf/inheritance";
import {
  projectRoleInspectionState,
  projectSeerState,
  projectWitchState,
} from "../mechanisms/roles/abilities";
import {
  getBlackMarketState,
  projectBlackMarketState,
} from "../mechanisms/roles/black_market_merchant/state";
import { allDeathGuns, projectDeathGun } from "../mechanisms/roles/death_abilities";
import { getGargoyleState } from "../mechanisms/roles/gargoyle/ports";
import { getRoleInspectionState } from "../mechanisms/roles/role_inspection/ports";
import { canGargoyleKnife } from "../mechanisms/roles/gargoyle/inheritance";
import {
  getMechanicalState,
  projectMechanicalState,
} from "../mechanisms/roles/mechanical_wolf/state";
import {
  getAwakenedState,
  projectAwakenedState,
} from "../mechanisms/roles/awakened_hidden_wolf/state";
import { ownNightActions } from "../mechanisms/roles/night_action_history";
import { getDebaterState, projectDebaterState } from "../mechanisms/roles/debater/state";
import { hasDebateCommit, debateVoteBlocked } from "../mechanisms/roles/debater/authority";
import { getCupidState, projectCupidState } from "../mechanisms/roles/cupid/state";
import { projectLover } from "../mechanisms/roles/cupid/relation";
import { getHybridState, projectHybridState } from "../mechanisms/roles/hybrid/state";
import { getMerchantState, projectMerchantState } from "../mechanisms/roles/miracle_merchant/state";
import { projectEclipseState } from "../mechanisms/roles/radiant_eclipse/ports";
import { COMPONENT } from "../../core/domain/components/names";
import { Camp, Role, type ActionRequest } from "@ai-werewolf-arena/game-contract";
import { allNightAbilities } from "../mechanisms";
import { projectNightAbility } from "./night-ability-projection";
import { getGuardState } from "../mechanisms/roles/guard/ports";
import { getHunterState } from "../mechanisms/roles/hunter/ports";
import { getWolfKingState } from "../mechanisms/roles/wolf_king/ports";
