/** 只供捕获 owner 使用的原位读取端口；回调不进入观察 DTO 或玩家策略。 */
export interface PlayerObservationQueries {
  world(): World;
  role(actorId: () => EntityId): RoleComponent | undefined;
  wolfTeammates(actorId: () => EntityId): EntityId[];
  catalog(): RoleCatalog;
}

/**
 * F01：只捕获当前 actor 自己的狼队资格，不从历史队友或请求的旧工具名单推断。
 * 原政策可运行自定义 callback，因此先读结果，再核对自己的角色编号、阵营和存活量；
 * 这只是观察快照，不是原生命／请求租约；实际提交仍由原机制验证，不返回拒绝原因。
 */
function captureCurrentWolfActions(
  request: ActionRequest,
  queries: PlayerObservationQueries,
): PlayerObservation["currentWolfActions"] {
  const world = queries.world(),
    actorId = request.actorId,
    role = world.getComponent(actorId, COMPONENT.Role),
    roleId = role?.role,
    permissions = wolfTeamPermissions(role, queries.catalog(), world),
    canChat = permissions.canChat === true,
    canVoteForKill = permissions.canVoteForKill === true;
  const current =
    world.getComponent(actorId, COMPONENT.Role) === role &&
    role?.role === roleId &&
    role?.camp === Camp.Wolf &&
    world.getComponent(actorId, COMPONENT.Alive)?.alive === true;
  return current ? { canChat, canVoteForKill } : { canChat: false, canVoteForKill: false };
}

export function capturePlayerObservation(
  request: ActionRequest,
  queries: PlayerObservationQueries,
): PlayerObservation {
  const role = queries.role(() => request.actorId);
  const dead = new Set<number>();
  for (const event of request.context.visible_events) {
    if (
      (event.type === "night_resolved" || event.type === "additional_deaths") &&
      Array.isArray(event.payload.deaths)
    ) {
      for (const id of event.payload.deaths) if (typeof id === "number") dead.add(id);
    }
    const target =
      event.type === "voted_out"
        ? event.payload.target
        : event.type === "wolf_self_destruct"
          ? event.payload.wolfId
          : event.type === "player_shot" ||
              event.type === "hunter_shot" ||
              event.type === "wolf_king_shot" ||
              event.type === "mechanical_shot"
            ? event.payload.targetId
            : undefined;
    if (typeof target === "number") dead.add(target);
    if (event.type === "white_wolf_king_self_destruct") {
      if (typeof event.payload.actorId === "number") dead.add(event.payload.actorId);
      if (typeof event.payload.targetId === "number") dead.add(event.payload.targetId);
    }
    if (event.type === "knight_duel") {
      const victim =
        event.payload.result === "wolf"
          ? event.payload.targetId
          : event.payload.result === "not_wolf"
            ? event.payload.actorId
            : undefined;
      if (typeof victim === "number") dead.add(victim);
    }
  }
  const ownState: PlayerObservation["ownState"] = {};
  if (role?.role === Role.FragrantPhantom && isFragrantPairBoard(queries.world())) {
    const known = fragrantPlayerKnowledge(queries.world(), request.phase, request.context.day);
    if (known.actorId === request.actorId) ownState.fragrantPhantom = known;
  }
  if (isNobleBodyBoard(queries.world())) {
    const known = getNobleBodyPlayerState(queries.world(), request.actorId, request.phase);
    if (known?.kind === "night_noble") ownState.nightNoble = known.state;
    if (known?.kind === "secret_body") ownState.secretBody = known.state;
  }
  const alchemist = projectAlchemist(role),
    raven = projectRaven(role);
  if (alchemist) ownState.alchemist = alchemist;
  if (raven) ownState.ravenClaw = raven;
  const modifier = readModifierState(scholarMentorStateForRole(role));
  if (modifier) ownState.scholarMentor = modifier;
  const timeConsort = projectTimeConsortState(role, request.context.day);
  if (timeConsort) ownState.timeConsort = timeConsort;
  const wolfSorcerer = projectWolfSorcererState(role);
  if (wolfSorcerer) ownState.wolfSorcerer = wolfSorcerer;
  const trickster = projectTricksterState(role);
  if (trickster) ownState.trickster = trickster;
  const prince = projectOrderPrinceState(role);
  if (prince) ownState.orderPrince = prince;
  const magician = projectMagicianState(role);
  if (magician) ownState.magician = magician;
  // 各机制拥有字段裁剪；此处只按原顺序组装，末尾统一脱离并冻结整个观察。
  const redMoon = projectRedMoonState(role);
  if (redMoon) ownState.redMoon = redMoon;
  const nightmare = projectNightmareShadowState(role);
  if (nightmare) ownState.nightmare = nightmare;
  const evilKnight = projectEvilKnightState(role);
  if (evilKnight) ownState.evilKnight = evilKnight;
  const thief = projectThiefState(role, queries.world()),
    choices = projectThiefChoices(queries.world(), request.actorId);
  if (thief) ownState.thief = { ...thief, ...(choices ?? {}) };
  const shape = projectShapeshifterState(role, queries.world()),
    shapeChoices = projectShapeshifterChoices(queries.world(), request.actorId);
  if (shape) ownState.shapeshifter = { ...shape, ...(shapeChoices ?? {}) };
  const wallNote = projectWallNote(queries.world(), request.actorId);
  if (wallNote) ownState.wallNote = wallNote;
  if (debateVoteBlocked(queries.world(), request.actorId, request.context.day))
    ownState.debatePenalty = { day: request.context.day };
  if (role?.role === Role.Debater) {
    const state = getDebaterState(role);
    if (state)
      ownState.debater = projectDebaterState(
        state,
        hasDebateCommit(queries.world(), request.actorId),
      );
  }
  const lover = projectLover(queries.world(), request.actorId);
  if (lover) ownState.lover = lover;
  if (role?.role === Role.Cupid) {
    const state = getCupidState(role);
    if (state) ownState.cupid = projectCupidState(state);
  }
  if (role?.role === Role.BlackMarketMerchant) {
    const state = getBlackMarketState(role);
    if (state) ownState.blackMarket = projectBlackMarketState(state);
  }
  const wedding = weddingActorView(queries.world(), request.actorId);
  if (wedding) ownState.wedding = wedding;
  if (role?.role === Role.GhostBride) {
    const brideState = weddingBrideState(queries.world(), request.actorId);
    if (brideState) ownState.ghostBride = brideState;
  }
  if (role?.role === Role.DemonHunter)
    ownState.demonHunter = projectDemonHunter(queries.world(), role);
  if (role?.role === Role.LonelyGirl)
    ownState.lonelyGirl = projectLonelyGirl(queries.world(), role);
  if (role?.role === Role.WildChild) ownState.wildChild = projectWildChild(queries.world(), role);
  if (role?.role === Role.Hybrid) {
    const state = getHybridState(role);
    if (state) ownState.hybrid = projectHybridState(state);
  }
  if (role?.role === Role.MiracleMerchant) {
    const state = getMerchantState(role);
    if (state) ownState.merchant = projectMerchantState(state);
  }
  if (role?.role === Role.EclipseMaid) ownState.eclipse = projectEclipseState(role);
  const witch = role ? getWitchState(role, request.context.ability_id) : undefined;
  const guard = role ? getGuardState(role, request.context.ability_id) : undefined;
  if (witch) ownState.witch = projectWitchState(witch);
  if (guard) ownState.guard = projectGuardState(guard);
  if (role?.role === Role.Hunter) {
    const state = getHunterState(role);
    if (state) ownState.hunter = projectHunterState(state);
  }
  if (role?.role === Role.WolfBeauty) {
    if (isAnimalDreamBoard(queries.world()))
      ownState.wolfBeauty = animalBeautyKnowledge(queries.world(), request.actorId);
    else {
      const state = getWolfBeautyState(role);
      if (state) ownState.wolfBeauty = projectWolfBeautyState(state);
    }
  }
  if (role?.role === Role.Bear) {
    if (isAnimalDreamBoard(queries.world())) ownState.bear = animalBearKnowledge(queries.world());
    else {
      const state = getBearState(role);
      if (state) ownState.bear = projectBearState(state);
    }
  }
  if (role?.role === Role.FoxCub)
    ownState.foxCub = animalFoxKnowledge(queries.world(), request.actorId);
  if (role?.role === Role.WhiteCat)
    ownState.whiteCat = animalCatKnowledge(queries.world(), request.actorId);
  if (role?.role === Role.Pufferfish)
    ownState.pufferfish = animalPufferKnowledge(queries.world(), request.actorId);
  if (role?.role === Role.HiddenWolf) {
    const state = getHiddenWolfState(role);
    ownState.hiddenWolf = {
      hasInheritedKnife: state?.hasInheritedKnife === true,
      canVoteForKill: canHiddenWolfKnife(role, queries.world()),
      ...(state?.campInspection === "netease_2020_good_v1"
        ? { campInspection: state.campInspection }
        : {}),
    };
  }
  if (role?.role === Role.Gargoyle)
    ownState.gargoyle = {
      hasInheritedKnife: getGargoyleState(role)?.hasInheritedKnife === true,
      canVoteForKill: canGargoyleKnife(role, queries.world()),
    };
  if (role?.role === Role.MechanicalWolf) {
    const state = getMechanicalState(role);
    if (state) ownState.mechanical = projectMechanicalState(state);
  }
  if (role?.role === Role.AwakenedHiddenWolf) {
    const state = getAwakenedState(role);
    if (state) ownState.awakened = projectAwakenedState(state);
  }
  if (role) {
    const inspection = getRoleInspectionState(role, request.context.ability_id);
    if (inspection) ownState.roleInspection = projectRoleInspectionState(inspection);
  }
  if (role?.role === Role.WolfKing) {
    const state = getWolfKingState(role);
    if (state) ownState.wolfKing = projectWolfKingState(state);
  }
  if (role?.role === Role.WhiteWolfKing) {
    const state = getWhiteWolfKingState(role);
    if (state) ownState.whiteWolfKing = projectWhiteWolfKingState(state);
  }
  if (role?.role === Role.Knight) {
    const state = getKnightState(role);
    if (state) ownState.knight = projectKnightState(state);
  }
  if (role?.role === Role.Gravekeeper) {
    const history = getGravekeeperState(role)?.history;
    ownState.gravekeeper = {
      history: Array.isArray(history)
        ? history.flatMap((item) => {
            const report = readGravekeeperReport(item);
            return report ? [report] : [];
          })
        : [],
    };
  }
  if (role?.role === Role.Idiot) {
    const state = getIdiotState(role);
    if (state) ownState.idiot = projectIdiotState(state);
  }
  const seer = role ? getSeerState(role, request.context.ability_id) : undefined;
  if (seer) ownState.seer = projectSeerState(seer);
  const dreamer = role ? getDreamerState(role, request.context.ability_id) : undefined;
  if (dreamer) ownState.dreamer = projectDreamerState(dreamer);
  const {
    wall_id: _wallId,
    death_action_id: _deathActionId,
    debate_id: _debateId,
    ...context
  } = request.context;
  return freezeObservation({
    request: { ...request, context },
    identity: {
      ...(role ? { role: role.role, camp: role.camp } : {}),
      name: queries.world().getComponent(request.actorId, COMPONENT.Identity)?.name,
    },
    knownAliveIds: queries
      .world()
      .entityIds()
      .filter((id) => !dead.has(id)),
    teammateIds: queries.wolfTeammates(() => request.actorId),
    ownState,
    ownNightActions: ownNightActions(queries.world(), request.actorId, request.context.day),
    abilities: allNightAbilities(role).map((ability) =>
      projectNightAbility(ability, request.context.day),
    ),
    deathAbilities: allDeathGuns(role).map(projectDeathGun),
    // 原知识、能力和发布存活字段已在原位置读完；新的自身资格单独捕获，不改写它们。
    currentWolfActions: captureCurrentWolfActions(request, queries),
  });
}

/**
 * 单元测试用已接受查验死因与明确反击政策验证恶灵骑士的独立库存。字面单次反射、免疫及
 * 序列化历史是预期，输入及字面／不可变 fixture 保持原样，不运行模型或完整对局。
 */
import { createAliveComponent } from "../../../../src/game/observation/component-presentation";
import type { EvilKnightShotPolicy } from "@ai-werewolf-arena/game-contract";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import { COMPONENT } from "../../../../src/core/domain/components/names";
import { type AliveComponent } from "../../../../src/core/domain/components/alive";
import type { RoleComponent } from "../../../../src/core/domain/components/role";
import type { StatusMarksComponent } from "../../../../src/core/domain/components/status_marks";
import { Camp, Role, StatusMark } from "../../../../src/core/domain/identity";
import { DeathCause } from "../../../../src/core/domain/deaths";
import { captureNightLife } from "../../../../src/core/domain/night_effects";
import { DamageResolutionSystem } from "../../../../src/core/domain/systems/damage_resolution_system";
import {
  captureEvilKnight,
  commitEvilKnightReflection,
  freshEvilKnightState,
  evilKnightNightShotImmune,
  getEvilKnightState,
} from "../../../../src/game/mechanisms/roles/evil_knight/state";

function fixture(policy: EvilKnightShotPolicy = "night_shot_immune") {
  const { world } = bootstrapGame(sixPlayerMvpConfig);
  const id = (kind: Role) =>
    world
      .entityIds()
      .find((id) => world.getComponent(id, COMPONENT.Role)?.role === kind)!;
  const knight = id(Role.Wolf),
    seer = id(Role.Seer),
    witch = id(Role.Witch) ?? id(Role.Villager);
  const role = world.getComponent(knight, COMPONENT.Role)!;
  world.getComponent(witch, COMPONENT.Role)!.role = Role.Witch;
  role.role = "evil_knight" as Role;
  const state = freshEvilKnightState(policy);
  (role as { privateState: Readonly<Record<string, unknown>> }).privateState = {
    evilKnight: state,
  };
  const binding = captureEvilKnight(world, captureNightLife(world, knight)!)!;
  let current = true;
  const commit = (kind: "seer_check" | "poison" = "seer_check") =>
    commitEvilKnightReflection(
      world,
      binding,
      captureNightLife(world, kind === "poison" ? witch : seer)!,
      kind,
      () => current,
    );
  return {
    world,
    knight,
    seer,
    witch,
    role,
    state,
    binding,
    commit,
    revoke: () => {
      current = false;
    },
  };
}
for (const first of ["seer_check", "poison"] as const) {
  test(`first accepted ${first} consumes only one reflection without consuming immunity`, () => {
    const f = fixture();
    const effect = f.commit(first)!;
    expect(effect.actorId).toBe(f.knight);
    expect(effect.target.id).toBe(first === "poison" ? f.witch : f.seer);
    expect(effect.isCurrent()).toBe(true);
    expect(f.state.reflectionRemaining).toBe(0);
    expect(f.commit(first === "poison" ? "seer_check" : "poison")).toBeNull();
    expect(evilKnightNightShotImmune(f.world, f.knight)).toBe(true);
  });
}
for (const shot of ["night_shot_immune", "hunter_shot_bypasses"] as const) {
  test(`shot policy ${shot} is independent from retaliation`, () => {
    const f = fixture(shot);
    expect(evilKnightNightShotImmune(f.world, f.knight)).toBe(shot === "night_shot_immune");
    expect(f.commit()).not.toBeNull();
    expect(evilKnightNightShotImmune(f.world, f.knight)).toBe(shot === "night_shot_immune");
  });
}
for (const mode of ["role", "state", "camp", "policy", "life", "revive"] as const) {
  test(`original knight ${mode} change revokes an accepted effect without refund`, () => {
    const f = fixture(),
      effect = f.commit()!;
    if (mode === "role") f.role.role = Role.Wolf;
    if (mode === "state")
      (f.role as { privateState: Readonly<Record<string, unknown>> }).privateState = {
        evilKnight: freshEvilKnightState(),
      };
    if (mode === "camp") f.role.camp = Camp.Good;
    if (mode === "policy") f.state.shotPolicy = "hunter_shot_bypasses";
    if (mode === "life") f.world.addComponent(f.knight, COMPONENT.Alive, createAliveComponent());
    if (mode === "revive") {
      const life = f.world.getComponent(f.knight, COMPONENT.Alive)!;
      life.alive = false;
      life.alive = true;
    }
    expect(effect.isCurrent()).toBe(false);
    expect(f.state.reflectionRemaining).toBe(0);
  });
}
test("revoked caster ownership cannot spend the reflection", () => {
  const f = fixture();
  f.revoke();
  expect(f.commit()).toBeNull();
  expect(f.state.reflectionRemaining).toBe(1);
});
test("late caster revocation cancels damage without refund", () => {
  const f = fixture(),
    effect = f.commit()!;
  f.revoke();
  expect(effect.isCurrent()).toBe(false);
  expect(f.state.reflectionRemaining).toBe(0);
});
test("replacement and revived caster lives cannot inherit retaliation", () => {
  for (const replace of [false, true]) {
    const f = fixture(),
      effect = f.commit()!;
    if (replace) f.world.addComponent(f.seer, COMPONENT.Alive, createAliveComponent());
    else {
      const life = f.world.getComponent(f.seer, COMPONENT.Alive)!;
      life.alive = false;
      life.alive = true;
    }
    expect(effect.isCurrent()).toBe(false);
  }
});
test("only native good Seer or Witch identity can trigger this finite resource", () => {
  const f = fixture();
  f.world.getComponent(f.seer, COMPONENT.Role)!.role = Role.Villager;
  expect(f.commit()).toBeNull();
  expect(f.state.reflectionRemaining).toBe(1);
});
test("state reading rejects accessor fields without executing them", () => {
  const f = fixture();
  let read = 0;
  Object.defineProperty(f.state, "reflectionRemaining", {
    get() {
      read++;
      return 1;
    },
  });
  expect(getEvilKnightState(f.role)).toBeUndefined();
  expect(read).toBe(0);
});
for (const marks of [
  [],
  [StatusMark.GuardMark],
  [StatusMark.HealMark],
  [StatusMark.GuardMark, StatusMark.HealMark],
  [StatusMark.PoisonMark],
  [StatusMark.WolfKillMark],
]) {
  test(`retaliation remains independent of ordinary marks ${marks.join(",")}`, () => {
    const f = fixture(),
      effect = f.commit()!;
    const status = f.world.getComponent(f.seer, COMPONENT.StatusMarks)!;
    for (const mark of marks) status.add(mark);
    const damage = new DamageResolutionSystem().resolve(f.world, {
      retaliationAttacks: [effect, effect],
    });
    expect(damage.deaths).toEqual([f.seer]);
    expect(
      damage.deathSources[f.seer]!.filter((c) => c === DeathCause.EvilKnightReflection),
    ).toHaveLength(1);
    expect(damage.deathSources[f.seer]).toEqual(
      expect.arrayContaining([
        DeathCause.EvilKnightReflection,
        ...(marks.includes(StatusMark.PoisonMark) ? [DeathCause.Poison] : []),
        ...(marks.includes(StatusMark.WolfKillMark) ? [DeathCause.WolfKill] : []),
      ]),
    );
    expect(f.world.getComponent(f.seer, COMPONENT.Alive)!.alive).toBe(true);
  });
}
test("revoked retaliation contributes no damage; absence of status marks does not suppress a valid effect", () => {
  const f = fixture(),
    effect = f.commit()!;
  f.world.removeComponent(f.seer, COMPONENT.StatusMarks);
  expect(
    new DamageResolutionSystem().resolve(f.world, { retaliationAttacks: [effect] }).deaths,
  ).toEqual([f.seer]);
  f.revoke();
  expect(
    new DamageResolutionSystem().resolve(f.world, { retaliationAttacks: [effect] }).deaths,
  ).toEqual([]);
});

for (const shot of ["night_shot_immune", "hunter_shot_bypasses"] as const) {
  for (const poison of [false, true]) {
    test(`persistent night immunity ${shot}/poison=${poison} survives spent reflection`, () => {
      const f = fixture(shot);
      f.commit();
      const marks = f.world.getComponent(f.knight, COMPONENT.StatusMarks)!;
      marks.add(StatusMark.WolfKillMark);
      if (poison) marks.add(StatusMark.PoisonMark);
      const damage = new DamageResolutionSystem().resolve(f.world, {
        nightImmunities: [f.binding],
      });
      expect(damage.deaths).toEqual([]);
      expect(marks.has(StatusMark.WolfKillMark)).toBe(false);
      expect(marks.has(StatusMark.PoisonMark)).toBe(false);
      expect(f.state.reflectionRemaining).toBe(0);
    });
  }
}
test("revoked immunity binding cannot protect a replacement body", () => {
  const f = fixture();
  f.world.addComponent(f.knight, COMPONENT.Alive, createAliveComponent());
  f.world
    .getComponent(f.knight, COMPONENT.StatusMarks)!
    .add(StatusMark.PoisonMark);
  const damage = new DamageResolutionSystem().resolve(f.world, { nightImmunities: [f.binding] });
  expect(damage.deaths).toEqual([f.knight]);
});
test("night immunity does not remove retaliation against its caster", () => {
  const f = fixture(),
    effect = f.commit()!;
  f.world
    .getComponent(f.knight, COMPONENT.StatusMarks)!
    .add(StatusMark.PoisonMark);
  const damage = new DamageResolutionSystem().resolve(f.world, {
    nightImmunities: [f.binding],
    retaliationAttacks: [effect],
  });
  expect(damage.deaths).toEqual([f.seer]);
  expect(damage.deathSources[f.seer]).toEqual([DeathCause.EvilKnightReflection]);
});

/**
 * 单元测试验证恶夜骑士本夜绑定的状态身份、安装失败前缀及实际夜枪保护短路。
 * 输入为真实 World／原体组件、手写同 Map 和故障 getter；原引用、读序及字面拒绝是独立预期。
 * 不提交反射、消费库存或运行整局／模型；同名旧属性注入不视为新 owner 的运行绑定。
 */
import { expect, test } from "bun:test";
import { Camp, Role } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../../src/core/domain/world";
import { COMPONENT } from "../../../../src/core/domain/components/names";
import { createRoleComponent } from "../../../../src/core/domain/components/role";
import { createAliveComponent } from "../../../../src/core/domain/components/alive";
import { captureNightLife } from "../../../../src/core/domain/night_effects";
import type { NightStageState, NightStageContext } from "../../../../src/game/mechanisms/stages/night/contracts";
import type { NightPipelineResult } from "../../../../src/game/engine/phase_pipeline/night_pipeline";
import { captureEvilKnight, freshEvilKnightState } from "../../../../src/game/mechanisms/roles/evil_knight/state";
import { installEvilKnightBoard, EVIL_KNIGHT_FRAME_STAGE } from "../../../../src/game/mechanisms/roles/evil_knight/night_frame";
import {
  hasEvilKnightNightBindings,
  installEvilKnightNightBindings,
  evilKnightNightBinding,
  captureEvilKnightNightShotProtection,
} from "../../../../src/game/mechanisms/roles/evil_knight/night-bindings";

function state(): NightStageState {
  return { wolfChatOrder: [], endedWolves: new Set(), wolfVotes: {}, wolfTarget: null, seerChecks: [] };
}
function fixture() {
  const world = new World(), actorId = world.createEntity(), role = createRoleComponent(Role.EvilKnight, Camp.Wolf), life = createAliveComponent();
  (role.privateState as Record<string, unknown>).evilKnight = freshEvilKnightState();
  world.addComponent(actorId, COMPONENT.Role, role);
  world.addComponent(actorId, COMPONENT.Alive, life);
  installEvilKnightBoard(world);
  const binding = captureEvilKnight(world, captureNightLife(world, actorId)!)!;
  return { world, actorId, role, life, binding };
}

test("same original Map and binding are retained, while old properties and cloned state do not inject", () => {
  const s = state(), f = fixture(), map = new Map([[f.actorId, f.binding]]);
  Object.defineProperty(s, "evilKnightBindings", { get() { throw new Error("retired_slot_must_not_read"); } });
  expect(hasEvilKnightNightBindings(s)).toBe(false);
  expect(evilKnightNightBinding(s, f.actorId)).toBeNull();
  installEvilKnightNightBindings(s, map);
  expect(hasEvilKnightNightBindings(s)).toBe(true);
  expect(evilKnightNightBinding(s, f.actorId)).toBe(f.binding);
  const protection = captureEvilKnightNightShotProtection(s);
  expect(protection(f.actorId)).toBe(true);
  expect(evilKnightNightBinding(state(), f.actorId)).toBeNull();
  // 描述器不会因注册而被读取；普通同形副本也没有本族身份记录。
  const clone = Object.assign({}, state());
  expect(captureEvilKnightNightShotProtection(clone)(f.actorId)).toBe(false);
  map.delete(f.actorId);
  expect(protection(f.actorId)).toBe(false);
  expect(evilKnightNightBinding(s, f.actorId)).toBeNull();
  // @ts-expect-error 通用夜间状态不再携带恶夜骑士私有绑定 Map。
  const retiredStateKey: keyof NightStageState = "evilKnightBindings";
  expect(retiredStateKey as string).toBe("evilKnightBindings");
  type Completed = Extract<NightPipelineResult, { interrupted: false }>;
  // @ts-expect-error 通用结果改为保护查询，不再返回私有 Map。
  const retiredResultKey: keyof Completed = "evilKnightBindings";
  expect(retiredResultKey as string).toBe("evilKnightBindings");
});

test("captured shot query reads Map then isCurrent then policy with original receivers", () => {
  const f = fixture(), s = state(), trace: string[] = [];
  let current = false, policy = "night_shot_immune" as "night_shot_immune" | "hunter_shot_bypasses";
  const record: typeof f.binding = {
    target: f.binding.target,
    get state() { trace.push("state"); return { ...f.binding.state, get shotPolicy() { trace.push("policy"); return policy; } }; },
    isCurrent() { expect(this).toBe(record); trace.push("current"); return current; },
  };
  const map = new Map([[f.actorId, record]]), get = map.get;
  map.get = function(id) { expect(this).toBe(map); trace.push("get"); return get.call(this, id); };
  installEvilKnightNightBindings(s, map);
  const query = captureEvilKnightNightShotProtection(s);
  expect(trace).toEqual([]);
  expect(query(f.actorId)).toBe(false);
  expect(trace).toEqual(["get", "current"]);
  current = true; trace.length = 0;
  expect(query(f.actorId)).toBe(true);
  expect(trace).toEqual(["get", "current", "state", "policy"]);
  policy = "hunter_shot_bypasses";
  expect(query(f.actorId)).toBe(false);
  expect(map.get(f.actorId)).toBe(record);
  // 结果在原输出点捕获旧 Map，而不是在夜枪查询时重新抓 state 或 World。
  installEvilKnightNightBindings(s, new Map());
  expect(evilKnightNightBinding(s, f.actorId)).toBeNull();
  policy = "night_shot_immune";
  expect(query(f.actorId)).toBe(true);
});

test("frame keeps three state reads and installed bindings when immune-array assignment throws", async () => {
  const f = fixture(), s = state(), error = new Error("immune_assignment_rejected");
  let reads = 0, assigned: unknown;
  Object.defineProperty(s, "nightImmunities", { set(value) { assigned = value; throw error; } });
  const ctx = { world: f.world, get state() { reads++; return s; } } as unknown as NightStageContext;
  await expect(EVIL_KNIGHT_FRAME_STAGE.execute(ctx)).rejects.toBe(error);
  expect(reads).toBe(3);
  expect(hasEvilKnightNightBindings(s)).toBe(true);
  const binding = evilKnightNightBinding(s, f.actorId);
  expect(binding?.state).toBe(f.binding.state);
  expect(assigned).toEqual([binding]);
  await expect(EVIL_KNIGHT_FRAME_STAGE.execute(ctx)).rejects.toThrow("evil_knight_night_reentry");
  expect(reads).toBe(4);
});

