    },
    makeRequest: (actorId, allowedTools, extras) => ({
      actorId,
      allowedTools,
      phase: Phase.Night,
      context: {
        day: 1,
        ...extras,
        visible_events: [],
        turn_constraints: {
          required_any_tools: allowedTools,
          min_valid_actions: 1,
          max_valid_actions: 1,
