        .filter((actor) => world.getComponent(actor, COMPONENT.Role)?.role === role),
    ensureMarks: (actor) => world.getComponent(actor, COMPONENT.StatusMarks)!,
    pickMajorityTarget: () => null,
    shuffleWolves: (ids) => ids,
    state: {
      wolfChatOrder: [],
      endedWolves: new Set(),
      wolfVotes: {},
      wolfTarget: null,
      seerChecks: [],
