  const run = async () => {
    await EVIL_KNIGHT_FRAME_STAGE.execute(ctx);
    for (const stage of WITCH_NIGHT_STAGES) await stage.execute(ctx);
    for (const stage of SEER_NIGHT_STAGES) await stage.execute(ctx);
