  Object.assign(red.privateState, { redMoon: redState });
  const redView = projectRedMoonState(red)!;
  expect(redView).toEqual({
    policy: "awa_red_moon_demon_v1",
    lastWolfBlastPolicy: "forbidden",
    blastDay: null,
    exileDay: 2,
    expirySettled: false,
  });
  expect(redView).not.toBe(redState);
  redView.expirySettled = true;
  expect(redState.expirySettled).toBe(false);
  Object.defineProperty(redState, "extra", { value: 1 });
  expect(projectRedMoonState(red)).toBeUndefined();

  const evil = createRoleComponent(Role.EvilKnight, Camp.Wolf);
  const evilState = {
    policy: "awa_evil_knight_v1",
    shotPolicy: "hunter_shot_bypasses",
    reflectionRemaining: 1,
  };
  Object.assign(evil.privateState, { evilKnight: evilState });
  expect(projectEvilKnightState(evil)).toEqual({
    policy: "awa_evil_knight_v1",
    shotPolicy: "hunter_shot_bypasses",
    reflectionRemaining: 1,
  });
  expect(projectEvilKnightState(evil)).not.toBe(evilState);
  evilState.reflectionRemaining = 3;
  expect(projectEvilKnightState(evil)).toBeUndefined();
});

test("nightmare copies ordered nullable history without array helpers or extra-entry accessors", () => {
  const role = createRoleComponent(Role.NightmareShadow, Camp.Wolf);
  const entry = { day: 1, targetId: null };
  const history = [entry, { day: 2, targetId: 4 }];
  Object.defineProperty(history, "map", {
    get() {
      throw new Error("array_map_must_not_run");
    },
  });
  Object.defineProperty(entry, "secret", {
    enumerable: true,
    get() {
      throw new Error("extra_entry_getter_must_not_run");
    },
  });
  Object.assign(role.privateState, {
    nightmareShadow: {
      policy: "awa_nightmare_dreamer_v1",
      fearActionPolicy: "required_when_legal",
      wolfActionPolicy: "no_blast_no_self_knife",
      packReady: true,
      lastDay: 2,
      lastTarget: 4,
      history,
    },
  });
  const view = projectNightmareShadowState(role)!;
  expect(view).toEqual({
    policy: "awa_nightmare_dreamer_v1",
    fearActionPolicy: "required_when_legal",
    wolfActionPolicy: "no_blast_no_self_knife",
    packReady: true,
    lastDay: 2,
    lastTarget: 4,
    history: [
      { day: 1, targetId: null },
      { day: 2, targetId: 4 },
    ],
  });
  expect(view.history).not.toBe(history);
  expect(view.history[0]).not.toBe(entry);
  view.history[0]!.targetId = 7;
  expect(entry.targetId).toBeNull();
  // 投影不是新的授权检查：既有槽位校验拒绝访问器时，不执行它或制造默认状态。
  Object.defineProperty(history[1]!, "targetId", {
    get() {
      throw new Error("malformed_target_getter_must_not_run");
    },
  });
  expect(projectNightmareShadowState(role)).toBeUndefined();
});

test("the observation consumer freezes the mechanism projection without changing live stock", () => {
  const world = new World();
  world.createEntity();
  const role = createRoleComponent(Role.EvilKnight, Camp.Wolf);
  const liveState = {
    policy: "awa_evil_knight_v1",
    shotPolicy: "night_shot_immune",
    reflectionRemaining: 0,
  };
  Object.assign(role.privateState, { evilKnight: liveState });
  world.addComponent(1, COMPONENT.Role, role);
  const request: ActionRequest = {
    actorId: 1,
    phase: Phase.Night,
    allowedTools: [],
    context: { day: 1, stage: "witch", visible_events: [], turn_constraints: {} },
  };
  const view = capturePlayerObservation(request, {
    world: () => world,
    role: () => role,
    wolfTeammates: () => [],
    catalog: () => getDefaultRoleCatalog(),
  });
  expect(view.ownState.evilKnight).toEqual({
    policy: "awa_evil_knight_v1",
    shotPolicy: "night_shot_immune",
    reflectionRemaining: 0,
  });
  expect(Object.isFrozen(view.ownState.evilKnight)).toBe(true);
  expect(Object.isFrozen(liveState)).toBe(false);
  liveState.reflectionRemaining = 1;
  expect(view.ownState.evilKnight!.reflectionRemaining).toBe(0);
});

/**
 * 单元测试：验证恶灵骑士有限配置。输入为字面政策组合与不可变公开示例；schema、往返、状态及具名拒绝采用精确预期，不执行模型或完整对局。
 */
import { expect, test } from "bun:test";
import { isEvilKnightPreset } from "../../../src/rulesets";
import { bootstrapGame } from "../../../src/app/bootstrap";
import { evilKnightTwelveConfig } from "../../../src/runtime/scenarios/evil_knight_twelve";
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
} from "../../../src/runtime/config/board_definition";
import { Role, WinCondition, WitchSelfHealRule } from "../../../src/core/domain/identity";
import type { BoardConfig } from "../../../src/core/domain/board";
import { boardConfigSchema } from "../../../src/core/domain/board_schema";
import { COMPONENT } from "../../../src/core/domain/components/names";
import type { RoleComponent } from "../../../src/core/domain/components/role";
import { getEvilKnightState } from "../../../src/game/mechanisms/roles/evil_knight/state";
for (const shotPolicy of ["night_shot_immune", "hunter_shot_bypasses"] as const) {
  for (const selfHeal of [WitchSelfHealRule.Disabled, WitchSelfHealRule.FirstNightOnly]) {
    test(`evil knight strict board roundtrip ${shotPolicy}/${selfHeal}`, () => {
      const config = structuredClone(evilKnightTwelveConfig);
      config.evilKnight!.shotPolicy = shotPolicy;
      config.witch!.canSelfHeal = selfHeal;
      expect(isEvilKnightPreset(config)).toBe(true);
      expect(boardConfigSchema.parse(config)).toEqual(config);
      expect(
        parseBoardDefinition(boardDefinitionFromConfig("evil-knight-test", config)).config,
      ).toEqual(config);
      const { world } = bootstrapGame(config);
      expect(world.entityIds()).toHaveLength(12);
      const knight = world
        .entityIds()
        .map((id) => world.getComponent(id, COMPONENT.Role))
        .find((r) => r?.role === Role.EvilKnight)!;
      expect(getEvilKnightState(knight)).toEqual({
        policy: "awa_evil_knight_v1",
        shotPolicy,
        reflectionRemaining: 1,
      });
    });
  }
}
const invalid: Array<[string, (c: BoardConfig) => void]> = [
  [
    "missing knight",
    (c) => {
      c.roleSetups.find((r) => r.role === Role.EvilKnight)!.role = Role.Wolf;
    },
  ],
  [
    "wrong deck count",
    (c) => {
      c.roleSetups[0]!.count++;
    },
  ],
  [
    "unsupported role",
    (c) => {
      c.roleSetups.find((r) => r.role === Role.Guard)!.role = Role.Dreamer;
    },
  ],
  [
    "unknown gun policy",
    (c) => {
      c.evilKnight!.shotPolicy = "other" as never;
    },
  ],
  [
    "unknown role policy",
    (c) => {
      c.evilKnight!.policy = "other" as never;
    },
  ],
  [
    "unknown parameter",
    (c) => {
      Object.assign(c.evilKnight!, { reset: true });
    },
  ],
  [
    "unbounded self heal",
    (c) => {
      c.witch!.canSelfHeal = WitchSelfHealRule.Always;
    },
  ],
  [
    "double potion",
    (c) => {
      c.witch!.potionPolicy = "awa_both_native_experimental_v1";
    },
  ],
  [
    "optional seer",
    (c) => {
      c.seer!.actionPolicy = "awa_optional_v1";
    },
  ],
  [
    "different victory",
    (c) => {
      c.winConditions = [WinCondition.WolfReachHalf];
    },
  ],
  [
    "mixed victory",
    (c) => {
      c.winConditions!.push(WinCondition.SlaughterCity);
    },
  ],
  [
    "initial sheriff",
    (c) => {
      c.initialSheriffSeat = 1;
    },
  ],
];
for (const [name, mutate] of invalid) {
  test(`finite evil knight preset rejects ${name}`, () => {
    const config = structuredClone(evilKnightTwelveConfig);
    mutate(config);
    expect(isEvilKnightPreset(config)).toBe(false);
    expect(() => bootstrapGame(config)).toThrow("evil_knight_preset_invalid");
  });
}

for (const shot of ["night_shot_immune", "hunter_shot_bypasses"] as const) {
  for (const selfHeal of [WitchSelfHealRule.Disabled, WitchSelfHealRule.FirstNightOnly] as const) {
    test(`public evil knight board ${shot}/${selfHeal} loads and exactly roundtrips`, async () => {
      const path = new URL(
        `../../../../configs.example/boards/awa_evil_knight_12_${shot}_${selfHeal}_v1.json`,
        import.meta.url,
      );
      const definition = await Bun.file(path).json();
      const parsed = parseBoardDefinition(definition);
      expect(isEvilKnightPreset(parsed.config)).toBe(true);
      expect(parsed.config.evilKnight?.shotPolicy).toBe(shot);
      expect(parsed.config.witch?.canSelfHeal).toBe(selfHeal);
      expect(boardDefinitionFromConfig(definition.id, parsed.config)).toEqual(definition);
    });
  }
}

controls.text:
/**
 * 负责普通角色私有槽的纯数据结构与有限只读类型。输入为原安装／复制数据，输出保留
 * 政策、可空选择、历史和学习技能的原可写／只读边界，本契约唯一声明这些公共结构。
 * 声明不验证角色、不保存活跃库存、不渲染玩家知识，也不授予 World、租约、回执或命令权。
 * 原引用、安装校验和生命周期仍归具体状态／效果所有者；这里不新增自定义初始化键的运行限制。
 */
import type { EntityId } from "./identity";
import type { RoleId } from "./role-ids";
import type { InspectionResult } from "./inspection";
import type { ExileFeedback } from "./events";
import type {
  CupidPolicy,
  DebaterPolicy,
  HunterDeathActionPolicy,
  DeathActionPolicy,
  BeautyDeathLinkPolicy,
  HiddenWolfCampInspectionPolicy,
} from "./boards";

export interface HunterState {
  deathActionPolicy?: HunterDeathActionPolicy;
  canShoot: boolean;
}

export interface WolfKingState {
  deathActionPolicy?: DeathActionPolicy;
  canShoot: boolean;
}

export interface WhiteWolfKingState {
  readonly canDetonate: boolean;
}

export interface KnightState {
  readonly canDuel: boolean;
}

export interface GravekeeperReport extends ExileFeedback {
  receivedDay: number;
}

export interface GravekeeperState {
  history: GravekeeperReport[];
}

export interface WolfBeautyState {
  deathLinkPolicy?: BeautyDeathLinkPolicy;
  targetId: EntityId | null;
  lastActedDay: number | null;
  history: Array<{ day: number; targetId: EntityId | null }>;
}

export interface BearState {
  history: Array<{ day: number; roared: boolean }>;
}

export interface HiddenWolfState {
  readonly hasInheritedKnife: boolean;
  campInspection?: HiddenWolfCampInspectionPolicy;
}

export interface GargoyleState {
  readonly hasInheritedKnife: boolean;
}

export interface IdiotState {
  revealed: boolean;
}

export type MechanicalMode = "kill" | "skill";

export type MechanicalSkill =
  | { kind: "villager" }
  | {
      kind: "inspection";
      history: Array<{
        day: number;
        targetId: EntityId;
        result: Extract<InspectionResult, { kind: "role" }>;
      }>;
    }
  | { kind: "poison"; remaining: 0 | 1 }
  | { kind: "guard"; lastTarget: EntityId | null; lastGuardDay: number | null }
  | { kind: "hunter"; canShoot: boolean; armed: boolean }
  | { kind: "wolf"; extraKnife: "available" | "spent" | "expired" };

/** 学习来源标签与 readyOnNight 分列；外层 readonly 不冻结 skill 内库存，实际资格仍由本族晚核。 */
export interface MechanicalLearning {
  readonly targetId: EntityId;
  readonly role: RoleId;
  readonly day: number;
  readonly readyOnNight: number;
  readonly skill: MechanicalSkill;
}

/** 模式、关闭日和继承历史不替代当前请求／生命许可；learned 与 skill 仍是原资源结构。 */
export interface MechanicalState {
  learned: MechanicalLearning | null;
  mimicClosedDay: number | null;
  mode: { day: number; kind: MechanicalMode } | null;
  hasInheritedKnife: boolean;
  firstKnifeNight: number | null;
  skillClosedDay: number | null;
}

export type AwakenedSkill =
  | { kind: "villager" }
  | { kind: "inspection"; abilityId: string | null }
  | { kind: "poison"; remaining: 0 | 1 }
  | { kind: "guard"; lastTarget: EntityId | null; lastGuardDay: number | null }
  | { kind: "hunter"; canShoot: boolean; armed: boolean }
  | { kind: "wolf"; extraKnife: "available" | "spent" };

export type AwakenedActiveSkill = Extract<AwakenedSkill, { kind: "poison" | "guard" | "wolf" }>;

export type AwakenedTemplateRole = Extract<
  RoleId,
  "villager" | "mirror_girl" | "witch" | "guard" | "hunter" | "wolf"
>;

/** activationNight 记录激活夜，activeFromNight 记录后续起效夜；可空声明不自动激活或执行技能。 */
export interface AwakenedLearning {
  readonly targetId: EntityId;
  readonly role: AwakenedTemplateRole;
  readonly day: number;
  activationNight: number | null;
  activeFromNight: number | null;
  readonly skill: AwakenedSkill;
}

export interface AwakenedState {
  learned: AwakenedLearning | null;
  mimicClosedDay: number | null;
  skillClosedDay: number | null;
  hasInheritedKnife: boolean;
  firstKnifeNight: number | null;
}

export type MiracleSkill = "check" | "poison" | "guard";

/** remaining 与 closedDay 分别记录本族库存和流程关闭；choice 为 null 不足以证明可以再交易。 */
export interface MerchantState {
  remaining: 0 | 1;
  closedDay: number | null;
  choice: { day: number; targetId: number; skill: MiracleSkill } | null;
}

export type BlackMarketSkill = "check" | "poison" | "gun";

export interface BlackMarketState {
  remaining: 0 | 1;
  closedDay: number | null;
  choice: { day: number; targetId: number; skill: BlackMarketSkill } | null;
}

export type HunterReadState = Readonly<HunterState>;
export type WolfKingReadState = Readonly<WolfKingState>;
export type WhiteWolfKingReadState = Readonly<WhiteWolfKingState>;
export type KnightReadState = Readonly<KnightState>;
export type IdiotReadState = Readonly<IdiotState>;
export type HiddenWolfReadState = Readonly<HiddenWolfState>;
export type GargoyleReadState = Readonly<GargoyleState>;
export type BearReadState = { readonly history: readonly Readonly<BearState["history"][number]>[] };
export type WolfBeautyReadState = Readonly<Omit<WolfBeautyState, "history">> & {
  readonly history: readonly Readonly<WolfBeautyState["history"][number]>[];
};
export type GravekeeperReadReport = Readonly<Omit<GravekeeperReport, "result">> & {
  readonly result: Readonly<GravekeeperReport["result"]>;
};
export type GravekeeperReadState = { readonly history: readonly GravekeeperReadReport[] };
/** 以下读取类型显式保留原嵌套边界；readonly 只约束类型读取，不复制、深冻结或授予提交权限。 */
export type MechanicalReadSkill =
  | Readonly<
      Extract<MechanicalSkill, { kind: "villager" | "poison" | "guard" | "hunter" | "wolf" }>
    >
  | (Readonly<Omit<Extract<MechanicalSkill, { kind: "inspection" }>, "history">> & {
      readonly history: readonly (Readonly<
        Omit<Extract<MechanicalSkill, { kind: "inspection" }>["history"][number], "result">
      > & {
        readonly result: Readonly<
          Extract<MechanicalSkill, { kind: "inspection" }>["history"][number]["result"]
        >;
      })[];
    });
export type MechanicalReadLearning = Readonly<Omit<MechanicalLearning, "skill">> & {
  readonly skill: MechanicalReadSkill;
};
export type MechanicalReadState = Readonly<Omit<MechanicalState, "learned" | "mode">> & {
  readonly learned: MechanicalReadLearning | null;
  readonly mode: Readonly<NonNullable<MechanicalState["mode"]>> | null;
};
export type AwakenedReadSkill = Readonly<AwakenedSkill>;
export type AwakenedReadActiveSkill = Extract<
  AwakenedReadSkill,
  { kind: "poison" | "guard" | "wolf" }
>;
export type AwakenedReadLearning = Readonly<Omit<AwakenedLearning, "skill">> & {
  readonly skill: AwakenedReadSkill;
};
export type AwakenedReadState = Readonly<Omit<AwakenedState, "learned">> & {
  readonly learned: AwakenedReadLearning | null;
};
export type MerchantReadState = Readonly<Omit<MerchantState, "choice">> & {
  readonly choice: Readonly<NonNullable<MerchantState["choice"]>> | null;
};
export type BlackMarketReadState = Readonly<Omit<BlackMarketState, "choice">> & {
  readonly choice: Readonly<NonNullable<BlackMarketState["choice"]>> | null;
};

export interface CupidState {
  policy: CupidPolicy;
  remaining: 0 | 1;
  choice: { day: 1; pairIds: [number, number] } | null;
}

export interface HybridState {
  remaining: 0 | 1;
  choice: { day: number; targetId: number } | null;
}

export interface WildChildState {
  policy: "awa_lui_meme_wild_child_v1";
  remaining: 0 | 1;
  status: "pending" | "chosen" | "transformed" | "active" | "closed";
  choice: { day: 1; targetId: number } | null;
  eligibleNight: number | null;
  activeFromNight: number | null;
}

export interface ThiefState {
  policy: "lui_meme_thief_two_extra_villagers_v1";
  remaining: 0 | 1;
  choice: 0 | 1 | null;
}

export interface ShapeshifterState {
  policy: "awa_netease_shapeshifter_two_extra_villagers_v1";
  remaining: 0 | 1;
  choice: 0 | 1 | null;
}

export interface DebaterState {
  policy: DebaterPolicy;
  remaining: 0 | 1;
  choice: { day: number; targetId: number } | null;
}

export type EvilKnightShotPolicy = "night_shot_immune" | "hunter_shot_bypasses";

export interface EvilKnightState {
  policy: "awa_evil_knight_v1";
  shotPolicy: EvilKnightShotPolicy;
  reflectionRemaining: 0 | 1;
}

export type FearActionPolicy = "optional" | "required_when_legal";

export type NightmareWolfActionPolicy = "standard" | "no_blast_no_self_knife";

export interface NightmareShadowState {
  policy: "awa_nightmare_dreamer_v1";
  fearActionPolicy: FearActionPolicy;
  wolfActionPolicy: NightmareWolfActionPolicy;
  packReady: boolean;
  lastDay: number | null;
  lastTarget: EntityId | null;
  history: { day: number; targetId: EntityId | null }[];
}

export interface MagicianChoice {
  day: number;
  pair: [number, number] | null;
}

export interface MagicianState {
  policy: "awa_magician_wolf_king_v1";
  firstNight: 1 | 2;
  deathShotTargetPolicy: "original" | "exchanged";
  history: MagicianChoice[];
}

export interface TricksterChoice {
  day: number;
  pair: [number, number] | null;
}

export interface TricksterState {
  policy: "awa_trickster_exile_v1";
  history: TricksterChoice[];
}

export interface WolfSorcererChoice {
  day: number;
  pair: [number, number] | null;
}

export interface WolfSorcererState {
  policy: "awa_wolf_sorcerer_seats_v1";
  firstNight: 1 | 2;
  history: WolfSorcererChoice[];
}

export type ReflectionScope = "whole_night" | "first_effect";

export interface TimeConsortChoice {
  day: number;
  targetId: number | null;
}

export interface TimeConsortState {
  policy: "awa_time_consort_reflection_v1";
  reflectionScope: ReflectionScope;
  history: TimeConsortChoice[];
  triggeredDay: number | null;
}

export type ReflectableSkill = "check" | "guard" | "poison";

export type ModifierCaster = "day_scholar" | "night_mentor";

export type ModifierMode = "enhance" | "weaken";

export interface ModifierChoice {
  day: number;
  mode: ModifierMode | null;
  targetId: number | null;
}

export interface ModifierState {
  policy: "awa_scholar_mentor_twelve_v1";
  caster: ModifierCaster;
  remaining: { enhance: number; weaken: number };
  history: ModifierChoice[];
}

export interface ModifierPlayer {
  id: number;
  role: string;
  camp: "good" | "wolf";
  alive: boolean;
}

export interface CommittedModifier {
  actorId: number;
  caster: ModifierCaster;
  mode: ModifierMode;
  targetId: number;
}

/** 增益解析结果包含死亡提案和效果描述；这些数据不直接标死、付款或取代原体回执。 */
export interface ModifierResolution {
  pendingDeaths: number[];
  conflict: "same_good" | "both_wolves" | null;
  goodEffects: Array<{ targetId: number; role: "seer" | "guard" | "witch"; mode: ModifierMode }>;
  bonusKnifeActorId: number | null;
  blockWolfKnife: boolean;
}

export interface LonelyGirlState {
  policy: "awa_netease_lonely_girl_v1";
  remaining: 0 | 1;
  choice: { day: 1; targetId: number } | null;
}

export type LastWolfBlastPolicy = "ends_game" | "forbidden";

export interface RedMoonState {
  policy: "awa_red_moon_demon_v1";
  lastWolfBlastPolicy: LastWolfBlastPolicy;
  blastDay: number | null;
  exileDay: number | null;
  expirySettled: boolean;
}

export type CupidReadState = Readonly<Omit<CupidState, "choice">> & {
  readonly choice: { readonly day: 1; readonly pairIds: readonly [number, number] } | null;
};
export type HybridReadState = Readonly<Omit<HybridState, "choice">> & {
  readonly choice: { readonly day: number; readonly targetId: number } | null;
};
export type WildChildReadState = Readonly<Omit<WildChildState, "choice">> & {
  readonly choice: { readonly day: 1; readonly targetId: number } | null;
};
export type ThiefReadState = Readonly<ThiefState>;
export type ShapeshifterReadState = Readonly<ShapeshifterState>;
export type DebaterReadState = Readonly<Omit<DebaterState, "choice">> & {
  readonly choice: { readonly day: number; readonly targetId: number } | null;
};
export type EvilKnightReadState = Readonly<EvilKnightState>;
export type NightmareShadowReadState = Readonly<Omit<NightmareShadowState, "history">> & {
  readonly history: readonly Readonly<NightmareShadowState["history"][number]>[];
};
export type MagicianReadChoice = Readonly<Omit<MagicianChoice, "pair">> & {
  readonly pair: readonly [number, number] | null;
};
export type MagicianReadState = Readonly<Omit<MagicianState, "history">> & {
  readonly history: readonly MagicianReadChoice[];
};
export type TricksterReadChoice = Readonly<Omit<TricksterChoice, "pair">> & {
  readonly pair: readonly [number, number] | null;
};
export type TricksterReadState = Readonly<Omit<TricksterState, "history">> & {
  readonly history: readonly TricksterReadChoice[];
};
export type WolfSorcererReadChoice = Readonly<Omit<WolfSorcererChoice, "pair">> & {
  readonly pair: readonly [number, number] | null;
};
export type WolfSorcererReadState = Readonly<Omit<WolfSorcererState, "history">> & {
  readonly history: readonly WolfSorcererReadChoice[];
};
export type TimeConsortReadState = Readonly<Omit<TimeConsortState, "history">> & {
  readonly history: readonly Readonly<TimeConsortChoice>[];
};
export type ModifierReadState = Readonly<Omit<ModifierState, "remaining" | "history">> & {
  readonly remaining: Readonly<ModifierState["remaining"]>;
  readonly history: readonly Readonly<ModifierChoice>[];
};
export type LonelyGirlReadState = Readonly<Omit<LonelyGirlState, "choice">> & {
  readonly choice: { readonly day: 1; readonly targetId: number } | null;
};
export type RedMoonReadState = Readonly<RedMoonState>;

/**
 * 负责原生命的存活值、版本及工厂描述符。输入为初始存活值；
 * 输出保留同一组件对象，只有存活值发生变化时推进版本，以识别复活后的新生命。
 * 身份表与描述符留在运行时；机制可记录版本数字快照（如 debatePenalty.lifeVersion），
 * 该数字不携带原组件或授权，描述符查询不执行访问器。
 * 展示语言与文案绑定已交游戏观察层；领域不格式化存活信息。
 */

/**
 * 存活状态组件：标记玩家是否仍在场。
 */
export interface AliveComponent {
  alive: boolean;
}

// 身份表只关联原组件；相同席位替换组件不会继承旧生命版本。
const lifeVersions = new WeakMap<AliveComponent, number>();
const originalDescriptors = new WeakMap<AliveComponent, PropertyDescriptor>();
/** 返回工厂访问器描述符的脱离副本；检查身份不会调用 alive getter。 */
export function aliveLifeDescriptor(component: AliveComponent): PropertyDescriptor | undefined {
  const descriptor = originalDescriptors.get(component);
  return descriptor && { ...descriptor };
}
/** 查询原版本；非工厂组件返回 undefined，不能据席位号伪造原体身份。 */
export function aliveLifeVersion(component: AliveComponent): number | undefined {
  return lifeVersions.get(component);
}

/**
 * 创建存活状态组件。
 */
export function createAliveComponent(
  alive: boolean = true,
): AliveComponent {
  const component: AliveComponent = {
    get alive() {
      return alive;
    },
    set alive(value: boolean) {
      if (typeof value !== "boolean") throw new Error("alive_state_invalid");
      // 死亡和复活都会推进版本；重复写同一值不制造新的死亡资格。
      if (value !== alive) {
        alive = value;
        lifeVersions.set(component, lifeVersions.get(component)! + 1);
      }
    },

  };
  originalDescriptors.set(component, Object.getOwnPropertyDescriptor(component, "alive")!);
  lifeVersions.set(component, 0);
  return component;
}

/**
 * 负责运行时夜间效果声明、原生命身份检查与机械伤害折叠。
 * 输入为原组件引用和已付效果；输出为有来源的 intent、原生命版本及保序伤害折叠。
 * 新 owned intent 消费类别／夜时点／原体因果链，旧注入对象保留原读取和接受宽度。
 * 所有者保留资源提交权限，句柄不进入序列化或玩家知识，本模块不将玩家标记为死亡。
 */
import type { DeathCause } from "./deaths";
import { COMPONENT } from "./components/names";
import { aliveLifeVersion, type AliveComponent } from "./components/alive";
import type { World } from "./world";
import type { EntityId } from "./identity";
import type { StatusMarksComponent } from "./components/status_marks";

/** 查询原生命和印记身份，不暴露组件修改命令。 */
export interface NightEffectQuery {
  getComponent(id: EntityId, name: typeof COMPONENT.Alive): Readonly<AliveComponent> | undefined;
  getComponent(id: EntityId, name: typeof COMPONENT.StatusMarks): object | undefined;
}

/** 仅供运行时的身份绑定；组件引用不进入事件或录制。 */
export interface NightLifeScope {
  readonly id: EntityId;
  readonly life: AliveComponent;
  readonly version: number;
}
/** 同一原体的只读查询视图；不复制组件，也不授予修改存活状态的权限。 */
export type NightLifeReadScope = Omit<NightLifeScope, "life"> & {
  readonly life: Readonly<AliveComponent>;
};
export interface NightPoisonClaim {
  readonly source: NightLifeScope;
  readonly target: NightLifeScope;
  readonly isCurrent?: () => boolean;
}

/**
 * 单次已付效果的运行时来源。源原体及目标句柄仅属于本夜，不进入事件或 schema2。
 * 每份效果的因果 ID 是独立 Symbol；捕获局部值只用于诊断描述，不是去重或稳定归档 ID。
 * 创建身份不读 World、时钟或 RNG，也不授予行动资格。
 */
export interface NightIntentOrigin {
  readonly family: "mechanical" | "awakened" | "witch" | "demon-witch" | "lucky" | "black-market" | "scholar-mentor";
  readonly day: number;
  readonly stage: "mechanical_skill" | "mechanical_attack" | "awakened_skill" | "awakened_attack" | "witch" | "lucky" | "black_market_recipient" | "scholar_mentor_bonus";
  readonly actorId: EntityId;
  readonly actorLife: NightLifeReadScope;
  /** 原行动目标；反射不改写它，实际反射落点另存 NightPoisonRoute。 */
  readonly requestedTargetId: EntityId | null;
  /** 创建时绑定的 effect.target.id，与 requestedTargetId 或反射落点分别表达。 */
  readonly effectiveTargetId: EntityId;
  readonly abilityId: string;
  readonly sourceVersion: number;
  readonly targetVersion: number;
  readonly sourceBody: Readonly<AliveComponent>;
  readonly targetBody: Readonly<AliveComponent>;
  /** 每份效果的独立运行时身份；description 只是诊断标签，不能用于去重。 */
  readonly causeId: symbol;
}
export type NightMechanicalIntentKind = "mechanical-shield" | "mechanical-attack" | "mechanical-failure";
export type NightAwakenedIntentKind = "awakened-shield" | "awakened-attack";
export type NightIntentKind = NightMechanicalIntentKind | NightAwakenedIntentKind | "original-poison";
export interface NightMechanicalIntent<K extends NightMechanicalIntentKind = NightMechanicalIntentKind> extends NightMechanicalEffect {
  readonly kind: K;
  readonly origin: NightIntentOrigin;
}
export interface NightAwakenedIntent<K extends NightAwakenedIntentKind = NightAwakenedIntentKind> extends NightAwakenedEffect {
  readonly kind: K;
  readonly origin: NightIntentOrigin;
}
export interface NightOriginalPoisonIntent extends NightPoisonClaim {
  readonly kind: "original-poison";
  readonly origin: NightIntentOrigin;
}
type OriginInput = Omit<NightIntentOrigin, "actorId" | "effectiveTargetId" | "causeId" | "sourceVersion" | "targetVersion" | "sourceBody" | "targetBody">;

// 只标记由本 owner 构造的对象身份，不复制 effects、不按 World 存第二份状态。
// 旧注入对象即使带有同名 getter，也不被当作新 intent 或读取其额外字段。
const ownedIntents = new WeakSet<object>();
function annotateIntent<T extends { readonly target: NightLifeScope }, K extends NightIntentKind>(
  effect: T,
  kind: K,
  origin: OriginInput,
  actorId: EntityId,
): T & Readonly<{ kind: K; origin: NightIntentOrigin }> {
  if (ownedIntents.has(effect)) throw new Error("night_effect_intent_already_owned");
  const effectiveTargetId = effect.target.id;
  const causeId = Symbol(`effect:${origin.day}:${origin.family}:${origin.stage}:${actorId}:${kind}:${origin.abilityId}:${origin.requestedTargetId}:${effectiveTargetId}`);
  const captured = Object.freeze({
    ...origin, actorId, effectiveTargetId, causeId, sourceVersion: origin.actorLife.version, targetVersion: effect.target.version,
    sourceBody: origin.actorLife.life, targetBody: effect.target.life,
  });
  // 只锁定新增协议字段，不冻结原 target/callback；整个 origin 不能被重写绕过原体校验。
  Object.defineProperties(effect, {
    kind: { value: kind, enumerable: true },
    origin: { value: captured, enumerable: true },
  });
  ownedIntents.add(effect);
  return effect as T & Readonly<{ kind: K; origin: NightIntentOrigin }>;
}
/** 机械盾、额外刀与重复守失败保持各自类别及原 owner callback。 */
export function mechanicalNightIntent<K extends NightMechanicalIntentKind>(
  kind: K, effect: NightMechanicalEffect, origin: OriginInput & { readonly family: "mechanical" },
): NightMechanicalIntent<K> {
  return annotateIntent(effect, kind, origin, effect.actorId);
}
/** 觉醒效果不因已付瓶数或首次死亡而丢失原 callback 的专有规则。 */
export function awakenedNightIntent<K extends NightAwakenedIntentKind>(
  kind: K, effect: NightAwakenedEffect, origin: OriginInput & { readonly family: "awakened" },
): NightAwakenedIntent<K> {
  return annotateIntent(effect, kind, origin, effect.actorId);
}
/** 原毒与机械返回毒是不同链路；此 factory 只标记原已付毒。 */
export function originalPoisonIntent(effect: NightPoisonClaim, origin: OriginInput): NightOriginalPoisonIntent {
  return annotateIntent(effect, "original-poison", origin, effect.source.id);
}

/**
 * 在原 target 读取点消费新协议的类别/夜时点/因果链；不替代原 current 或生命重检。
 * 旧 claim/effect 完整保留原读取行为，包括额外 kind/origin getter 从不被调用。
 * 新协议错类别/夜时点属于约束强化；拒绝时不回滚先前已付库存或事实。
 */
export function nightIntentTarget(
  effect: { readonly target: NightLifeScope }, expected: NightIntentKind, night?: () => number | undefined,
): NightLifeScope {
  if (ownedIntents.has(effect)) {
    const intent = effect as Readonly<{ kind: NightIntentKind; origin: NightIntentOrigin; target: NightLifeScope }>;
    if (intent.kind !== expected) throw new Error("night_effect_intent_kind_mismatch");
    const day = night?.();
    if (day !== undefined && intent.origin.day !== day) throw new Error("night_effect_intent_night_mismatch");
    if (!intent.origin.causeId || intent.origin.actorLife.id !== intent.origin.actorId || intent.origin.actorLife.version !== intent.origin.sourceVersion || intent.origin.actorLife.life !== intent.origin.sourceBody)
      throw new Error("night_effect_intent_source_mismatch");
    const target = intent.target;
    if (target.id !== intent.origin.effectiveTargetId || target.version !== intent.origin.targetVersion || target.life !== intent.origin.targetBody)
      throw new Error("night_effect_intent_target_mismatch");
    return target;
  }
  return effect.target;
}

/** 仅在原毒 source 读取位置校验源句柄，不新增施毒者存活或窗口规则。 */
export function nightIntentPoisonSource(claim: NightPoisonClaim): NightLifeScope {
  const source = claim.source;
  if (ownedIntents.has(claim) && source !== (claim as NightOriginalPoisonIntent).origin.actorLife)
    throw new Error("night_effect_intent_source_mismatch");
  return source;
}

/** 在原反射 actorId 读取点核对来源，旧对象仍只执行一次同一属性读取。 */
export function nightIntentMechanicalActor(effect: NightMechanicalEffect): EntityId {
  const actorId = effect.actorId;
  if (ownedIntents.has(effect) && actorId !== (effect as NightMechanicalIntent).origin.actorId)
    throw new Error("night_effect_intent_source_mismatch");
  return actorId;
}
export interface NightFoxInspectionClaim {
  readonly target: NightLifeScope;
  /** 首日警长结算前切换阶段不会撤销原目标绑定。 */
  readonly isTargetCurrent: () => boolean;
  readonly isCurrent: () => boolean;
}
export interface NightGuardClaim {
  readonly isCurrent?: () => boolean;
  readonly contribution?: object;
  readonly target: NightLifeScope;
  readonly marks: StatusMarksComponent;
}
export interface NightMerchantBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export interface NightBlackMarketBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
/** 吞噬反噬是独立攻击，不归入商人效果或梦境死亡。 */
export interface NightRadiantBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function captureNightLife(world: World, id: EntityId): NightLifeScope | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  return life?.alive && version !== undefined ? { id, life, version } : null;
}
export function sameNightLife(world: NightEffectQuery, scope: NightLifeReadScope): boolean {
  return (
    world.getComponent(scope.id, COMPONENT.Alive) === scope.life &&
    aliveLifeVersion(scope.life) === scope.version
  );
}
export function livingNightLife(world: NightEffectQuery, scope: NightLifeReadScope): boolean {
  return sameNightLife(world, scope) && scope.life.alive;
}

/** 已提交机械效果绑定原体；库存仍由具体机制所有者持有。 */
export interface NightMechanicalEffect {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  /** 只读重检提交者的角色、状态、生命与阶段，不修改原体。 */
  readonly isCurrent: () => boolean;
}
export interface NightMechanicalEffects {
  readonly shields: readonly NightMechanicalEffect[];
  readonly attacks: readonly NightMechanicalEffect[];
  readonly failures: readonly NightMechanicalEffect[];
}
/** 觉醒守护吸收毒药；其额外狼刀按普通保护规则判定。 */
export interface NightAwakenedEffect {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  /** 已付款效果重检原所有者；行动窗口关闭不等于撤销合法已付效果。 */
  readonly isCurrent: () => boolean;
}
export interface NightAwakenedEffects {
  readonly shields: readonly NightAwakenedEffect[];
  readonly attacks: readonly NightAwakenedEffect[];
}
/** 仅全知视角的因果事实；玩家投影不得泄露施毒来源。 */
export interface NightPoisonReflection {
  readonly actorId: EntityId;
  readonly protectedTargetId: EntityId;
  readonly casterId: EntityId;
}
/** 原毒经折叠后的实际去向；反射改变目标，但保留原独立因果身份及原体链。 */
export interface NightPoisonRoute {
  readonly route: "direct" | "reflected";
  readonly origin: NightIntentOrigin;
  readonly targetId: EntityId;
  readonly target: NightLifeReadScope;
}
// 因果链属于本次伤害计划，而非另一份世界状态。非枚举 Symbol 保持原输出／归档形状。
const POISON_ROUTES = Symbol("night_poison_routes");
const NO_POISON_ROUTES: readonly NightPoisonRoute[] = Object.freeze([]);
// 只登记本 owner 的返回对象身份；外部 legacy plan／Proxy 不读取新增 Symbol。
// 路由数据仍仅存于同一计划，这个品牌不保存目标、库存或另一份世界状态。
const ownedDamagePlans = new WeakSet<object>();
export interface MechanicalDamagePlan {
  readonly shields: ReadonlySet<EntityId>;
  readonly directPoisonTargets: ReadonlySet<EntityId>;
  readonly reflectedPoisonTargets: ReadonlySet<EntityId>;
  readonly attacks: ReadonlySet<EntityId>;
  readonly failures: ReadonlySet<EntityId>;
  readonly reflections: readonly NightPoisonReflection[];
  readonly [POISON_ROUTES]?: readonly NightPoisonRoute[];
}
/** Wave／单目标结算的运行时输入；这里只读既有折叠结果，不重查资格或库存。 */
export function nightPoisonRoutes(plan: MechanicalDamagePlan): readonly NightPoisonRoute[] {
  return ownedDamagePlans.has(plan) ? plan[POISON_ROUTES] ?? NO_POISON_ROUTES : NO_POISON_ROUTES;
}
/** owned 路由参与毒的接受；旧集合仍含 owned 目标并作 OR 后备，尚未被路由完全替代。 */
export function nightPoisonRouteTargets(
  plan: MechanicalDamagePlan, targetId: EntityId, route: NightPoisonRoute["route"],
): boolean {
  return nightPoisonRoutes(plan).some((cause) => cause.route === route && cause.targetId === targetId) ||
    (route === "direct" ? plan.directPoisonTargets : plan.reflectedPoisonTargets).has(targetId);
}
function recordOwnedPoisonRoute(
  routes: NightPoisonRoute[], poison: NightPoisonClaim, route: NightPoisonRoute["route"],
  target: NightLifeScope, targetId: EntityId,
): void {
  if (ownedIntents.has(poison))
    routes.push(Object.freeze({ route, origin: (poison as NightOriginalPoisonIntent).origin, targetId, target }));
}
/** 每份原毒只折叠一次；反射毒不再送回盾内，避免递归反射。 */
export function planMechanicalDamage(
  world: NightEffectQuery,
  effects: NightMechanicalEffects | undefined,
  poisons: readonly NightPoisonClaim[] = [],
  absorbedPoisonTargets: ReadonlySet<EntityId> = new Set(),
  intentNight?: () => number | undefined,
): MechanicalDamagePlan {
  // 有效盾按贡献顺序覆盖同一目标，反射事实使用最终选中盾的行动者。
  const shields = new Map<EntityId, NightMechanicalEffect>();
  for (const shield of effects?.shields ?? []) {
    if (shield.isCurrent() && livingNightLife(world, nightIntentTarget(shield, "mechanical-shield", intentNight))) {
      shields.set(nightIntentTarget(shield, "mechanical-shield", intentNight).id, shield);
    }
  }
  const directPoisonTargets = new Set<EntityId>();
  const reflectedPoisonTargets = new Set<EntityId>();
  const reflections: NightPoisonReflection[] = [];
  const poisonRoutes: NightPoisonRoute[] = [];
  // current 回调仅显式 false 撤销已付毒；直接毒不新增源存活门禁，反射才在原位置重检源生命。
  for (const poison of poisons) {
    if (
      poison.isCurrent?.() === false ||
      !livingNightLife(world, nightIntentTarget(poison, "original-poison", intentNight)) ||
      absorbedPoisonTargets.has(nightIntentTarget(poison, "original-poison", intentNight).id)
    )
      continue;
    const shield = shields.get(nightIntentTarget(poison, "original-poison", intentNight).id);
    if (!shield) {
      const target = nightIntentTarget(poison, "original-poison", intentNight), targetId = target.id;
      directPoisonTargets.add(targetId);
      recordOwnedPoisonRoute(poisonRoutes, poison, "direct", target, targetId);
      continue;
    }
    if (livingNightLife(world, nightIntentPoisonSource(poison))) {
      const target = nightIntentPoisonSource(poison), targetId = target.id;
      reflectedPoisonTargets.add(targetId);
      recordOwnedPoisonRoute(poisonRoutes, poison, "reflected", target, targetId);
      reflections.push({
        actorId: nightIntentMechanicalActor(shield),
        protectedTargetId: nightIntentTarget(poison, "original-poison", intentNight).id,
        casterId: nightIntentPoisonSource(poison).id,
      });
    }
  }
  const attacks = new Set<EntityId>();
  const failures = new Set<EntityId>();
  for (const attack of effects?.attacks ?? []) {
    if (attack.isCurrent() && livingNightLife(world, nightIntentTarget(attack, "mechanical-attack", intentNight)))
      attacks.add(nightIntentTarget(attack, "mechanical-attack", intentNight).id);
  }
  for (const failure of effects?.failures ?? []) {
    if (failure.isCurrent() && livingNightLife(world, nightIntentTarget(failure, "mechanical-failure", intentNight)))
      failures.add(nightIntentTarget(failure, "mechanical-failure", intentNight).id);
  }
  const plan: MechanicalDamagePlan = {
    shields: new Set(shields.keys()),
    directPoisonTargets,
    reflectedPoisonTargets,
    attacks,
    failures,
    reflections,
  };
  Object.defineProperty(plan, POISON_ROUTES, { value: Object.freeze(poisonRoutes) });
  ownedDamagePlans.add(plan);
  return plan;
}

/** 有限纯白查验规则的原所有者与目标绑定。 */
export interface NightInspectionAttack {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  readonly cause: DeathCause.PureWhiteInspection | DeathCause.WolfWitchInspection;
  readonly isCurrent: () => boolean;
}

/** 恶灵骑士反击在原行动接受时付款，于夜末按原体绑定结算。 */
export interface NightRetaliationAttack {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}

/** 持续被动夜间免疫保留原生命与角色授权。 */
export interface NightImmunityClaim {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}

/**
 * 负责绑定原生已付效果命令与原延迟控制器。输入为原阶段上下文、回执／能力和延迟参数；
 * 输出保原付款前缀、增益事实及反射；命令绑定本身不读 World、事件、状态或来源，也不授权新资格。
 * 反射先取原提交 callee，再读取 World、本族同夜 binding、source 和种类；原状态命令负责资格与消费。
 * 原 context／receipt receiver 与每次读取点保持，不增加退款、复制或序列化运行句柄。
 */
import { Role } from "../core/domain/identity";
import type { NightLifeScope } from "../core/domain/night_effects";
import type { NightStageContext } from "../game/mechanisms/stages/night/contracts";
import type { NightAbilityReadView } from "../game/mechanisms/roles/abilities";
import {
  isScholarMentorBoard,
  recordScholarMentorNativeTarget,
  scholarMentorKnifeEligible,
} from "../game/mechanisms/roles/scholar_mentor/ports";
import {
  isEvilKnightBoard,
  commitEvilKnightReflection,
  evilKnightNightBinding,
} from "../game/mechanisms/roles/evil_knight/ports";
import {
  commitTimeConsortEffect,
  type TimeConsortReceipt,
} from "../game/mechanisms/roles/time_wolf_consort/ports";
import {
  loadDemonNativeNightController,
  loadDemonNativePotionController,
} from "../game/mechanisms/roles/demon_hunter/ports";
import type { NativeReflectedTarget } from "./native-night-target-policy";

export interface NativeNightEffects {
  commitReflectedTarget(
    receipt: NativeReflectedTarget | null,
    day: number,
    sourceId: number,
    kind: "check" | "guard" | "poison",
  ): void;
  recordModifierTarget(
    day: number,
    actorId: number,
    kind: "check" | "guard" | "poison",
    targetId: () => number | null,
  ): void;
  recordKnifeModifierTarget(targetId: () => number | null): void;
  commitNativeReflection(
    kind: "seer_check" | "poison",
    ability: NightAbilityReadView<"seer_check" | "potion">,
    targetId: number,
    source: () => NightLifeScope,
    isCurrent: () => boolean,
  ): void;
  loadSealedNightController: typeof loadDemonNativeNightController;
  loadSealedPotionController: typeof loadDemonNativePotionController;
}

/** 同一阶段上下文仍在原命令调用点交给已付效果命令，不复制引用或提前读取。 */
export function bindNativeNightEffects(context: () => NightStageContext): NativeNightEffects {
  return Object.freeze({
    commitReflectedTarget(
      receipt: NativeReflectedTarget | null,
      day: number,
      sourceId: number,
      kind: "check" | "guard" | "poison",
    ) {
      commitTimeConsortEffect(context(), receipt as TimeConsortReceipt | null, day, sourceId, kind);
    },
    recordModifierTarget(
      day: number,
      actorId: number,
      kind: "check" | "guard" | "poison",
      targetId: () => number | null,
    ) {
      if (isScholarMentorBoard(context().world))
        recordScholarMentorNativeTarget(context().world, day, actorId, kind, targetId());
    },
    recordKnifeModifierTarget(targetId: () => number | null) {
      if (isScholarMentorBoard(context().world)) {
        const actor = context()
          .world.getAliveEntityIds()
          .find((id) => scholarMentorKnifeEligible(context().world, context().currentDay(), id));
        if (actor !== undefined)
          recordScholarMentorNativeTarget(
            context().world,
            context().currentDay(),
            actor,
            "kill",
            targetId(),
          );
      }
    },
    commitNativeReflection(
      kind: "seer_check" | "poison",
      ability: NightAbilityReadView<"seer_check" | "potion">,
      targetId: number,
      source: () => NightLifeScope,
      isCurrent: () => boolean,
    ) {
      if (isEvilKnightBoard(context().world)) {
        if (
          ability.source.kind !== "native" ||
          ability.source.role !== (kind === "seer_check" ? Role.Seer : Role.Witch)
        )
          throw new Error(
            kind === "seer_check"
              ? "evil_knight_seer_source_invalid"
              : "evil_knight_witch_source_invalid",
          );
        const reflection = commitEvilKnightReflection(
          context().world,
          evilKnightNightBinding(context().state, targetId),
          source(),
          kind,
          isCurrent,
        );
        if (reflection) (context().state.retaliationAttacks ??= []).push(reflection);
      }
    },
    loadSealedNightController: loadDemonNativeNightController,
    loadSealedPotionController: loadDemonNativePotionController,
  });
}
